-- Villa Janat (Marrakech): new villa on villas.html. No price (price_from stays null: partner rates are never shown).
insert into public.villas (name, area, area_en, has_pool, description, description_en, amenities, amenities_en, price_from, photo_path, photos, active, sort_order)
